def json_pointer(doc, pointer: str):
    if pointer == "":
        return doc
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise ValueError("JSON Pointer must start with '/'")

    current = doc

    for raw_segment in pointer[1:].split("/"):
        # Validate and decode RFC 6901 escape sequences in the required order.
        i = 0
        decoded = []
        while i < len(raw_segment):
            if raw_segment[i] == "~":
                if i + 1 >= len(raw_segment) or raw_segment[i + 1] not in "01":
                    raise ValueError("Invalid escape sequence in JSON Pointer")
                decoded.append("~" if raw_segment[i + 1] == "0" else "/")
                i += 2
            else:
                decoded.append(raw_segment[i])
                i += 1
        segment = "".join(decoded)

        if isinstance(current, dict):
            if segment not in current:
                raise ValueError("Missing key")
            current = current[segment]
        elif isinstance(current, list):
            if not segment or any(ch not in "0123456789" for ch in segment):
                raise ValueError("Invalid list index")
            if len(segment) > 1 and segment[0] == "0":
                raise ValueError("Invalid list index")
            index = int(segment)
            if index >= len(current):
                raise ValueError("List index out of range")
            current = current[index]
        else:
            raise ValueError("Cannot index into this value")

    return current
